import { getAllProducts } from '@/lib/db';
import { cacheTag } from 'next/cache';
import { revalidateTag } from 'next/cache';

// Child component that fetches and caches product data
async function ProductList() {
  'use cache';
  cacheTag('products');

  const products = await getAllProducts();

  return (
    <div style={{ marginBottom: '2rem' }}>
      <h2>Products (Cached)</h2>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {products.map((product) => (
          <li key={product.id} style={{
            padding: '0.5rem',
            margin: '0.5rem 0',
            border: '1px solid #ddd',
            borderRadius: '4px'
          }}>
            <strong>{product.name}</strong> - ${product.price}
          </li>
        ))}
      </ul>
      <p style={{ fontSize: '0.875rem', color: '#666' }}>
        Last fetched: {new Date().toLocaleTimeString()}
      </p>
    </div>
  );
}

export default function Page() {
  // Server action for cache invalidation
  async function invalidateProductCache() {
    'use server';
    revalidateTag('products');
  }

  return (
    <div style={{ padding: '2rem', maxWidth: '600px', margin: '0 auto' }}>
      <h1>Product Listing with Selective Cache Invalidation</h1>

      <ProductList />

      <form action={invalidateProductCache}>
        <button
          type="submit"
          style={{
            padding: '0.75rem 1.5rem',
            backgroundColor: '#0070f3',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer',
            fontSize: '1rem',
            fontWeight: 'bold'
          }}
        >
          Invalidate Product Cache
        </button>
      </form>

      <div style={{
        marginTop: '2rem',
        padding: '1rem',
        backgroundColor: '#f5f5f5',
        borderRadius: '4px'
      }}>
        <h3>How it works:</h3>
        <ul style={{ fontSize: '0.875rem' }}>
          <li>Product data is fetched using getAllProducts() from lib/db</li>
          <li>The ProductList component uses 'use cache' directive for caching</li>
          <li>Data is tagged with "products" cache tag using cacheTag()</li>
          <li>Clicking the button triggers a server action that calls revalidateTag('products')</li>
          <li>This invalidates only the "products" cache, not other cached data</li>
          <li>The timestamp shows when data was last fetched</li>
        </ul>
      </div>
    </div>
  );
}

